using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.VTS.AreasComunes;namespace GraphApi.Services.VTS.AreasComunes{    public class AreasComunesService : IAreasComunesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public AreasComunesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadAreasComunes>> GetAreasComunes(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM vts.AreasComunes (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadAreasComunes>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetAreasComunesDynamic(            int? areasComunesID,            string? areasComunes,            string? descripcionAreasComunes,            int? capacidad,            bool? requiereReservacion,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "AreasComunesID, AreasComunes, DescripcionAreasComunes, Capacidad, RequiereReservacion, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM vts.AreasComunes (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (areasComunesID.HasValue)            {                vSql.Append(" AND AreasComunesID = @AreasComunesID");                vParameters.Add("AreasComunesID",areasComunesID);            }            if (!string.IsNullOrWhiteSpace(areasComunes))            {                vSql.Append(" AND AreasComunes LIKE @AreasComunes");                vParameters.Add("AreasComunes",$"%{areasComunes}%");            }            if (!string.IsNullOrWhiteSpace(descripcionAreasComunes))            {                vSql.Append(" AND DescripcionAreasComunes LIKE @DescripcionAreasComunes");                vParameters.Add("DescripcionAreasComunes",$"%{descripcionAreasComunes}%");            }            if (requiereReservacion.HasValue)            {                vSql.Append(" AND RequiereReservacion = @RequiereReservacion");                vParameters.Add("RequiereReservacion", requiereReservacion.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadAreasComunes> CreateAreasComunes(clCreateAreasComunes objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO vts.AreasComunes                (AreasComunes, DescripcionAreasComunes, Capacidad, RequiereReservacion, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@AreasComunes, @DescripcionAreasComunes, @Capacidad, @RequiereReservacion, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.AreasComunes,                objInput.DescripcionAreasComunes,                objInput.Capacidad,                objInput.RequiereReservacion,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT AreasComunesID, AreasComunes, DescripcionAreasComunes, Capacidad, RequiereReservacion, bEliminado                FROM vts.AreasComunes (NOLOCK)                WHERE AreasComunesID = @AreasComunesID;";            var vReadParams = new { AreasComunesID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadAreasComunes>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el AreasComune con ID {vNewId}.");            return vCreated;        }        public async Task<clReadAreasComunes?> UpdateAreasComunes(clUpdateAreasComunes objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("AreasComunesID", objInput.AreasComunesID);            if (objInput.AreasComunes is not null)            {                vSets.Add("AreasComunes = @AreasComunes");                vParameters.Add("AreasComunes", objInput.AreasComunes);            }            if (objInput.DescripcionAreasComunes is not null)            {                vSets.Add("DescripcionAreasComunes = @DescripcionAreasComunes");                vParameters.Add("DescripcionAreasComunes", objInput.DescripcionAreasComunes);            }            if (objInput.Capacidad != null)            {                vSets.Add("Capacidad = @Capacidad");                vParameters.Add("Capacidad", objInput.Capacidad);            }            if (objInput.RequiereReservacion != null)            {                vSets.Add("RequiereReservacion = @RequiereReservacion");                vParameters.Add("RequiereReservacion", objInput.RequiereReservacion);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE vts.AreasComunes                SET {vSetClause}                WHERE AreasComunesID = @AreasComunesID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT AreasComunesID, AreasComunes, DescripcionAreasComunes, Capacidad, RequiereReservacion, bEliminado                FROM vts.AreasComunes (NOLOCK)                WHERE AreasComunesID = @AreasComunesID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadAreasComunes>(sSelect, new {  objInput.AreasComunesID });        }        public async Task<bool> DeleteAreasComunes(int nAreasComunesID)        {            const string sSql = @"                DELETE FROM vts.AreasComunes                WHERE AreasComunesID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nAreasComunesID });            return vAffected > 0;        }    }}